import React, { useState, useEffect } from 'react';

export default function Profile() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Grabs the specific user data saved during Login
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  // Default values if no user is found yet
  const displayUser = user || {
    fullName: "Guest User",
    email: "guest@example.com",
    level: 1,
    xp: 0,
    nextXp: 500
  };

  const progressPercent = (displayUser.xp / displayUser.nextXp) * 100;

  return (
    <div className="profile-page-wrapper">
      <div className="profile-header-card">
        <div className="profile-banner-gradient"></div>
        <div className="profile-info-row">
          <div className="profile-avatar-large">
            {/* Dynamic Initial */}
            <span className="avatar-icon">{displayUser.fullName.charAt(0).toUpperCase()}</span>
          </div>
          <div className="profile-user-details">
            <h1>{displayUser.fullName}</h1>
            <p>VidyaQuest Learner • {displayUser.email}</p>
          </div>
          <div className="profile-actions">
            <button className="edit-btn">✏️ Edit Profile</button>
            <button className="signout-btn" onClick={() => { localStorage.clear(); window.location.href = '/login'; }}>
              📤 Sign Out
            </button>
          </div>
        </div>
      </div>

      <div className="profile-stats-grid">
        <div className="profile-section-card">
          <div className="section-header"><h3>🏆 Level Progress</h3></div>
          <div className="level-card-content">
             <div className="level-badge">{displayUser.level}</div>
             <div className="level-details">
                <div className="level-text">Level {displayUser.level} <span>{displayUser.xp} / {displayUser.nextXp} XP</span></div>
                <div className="progress-bar-container">
                  <div className="progress-fill" style={{ width: `${progressPercent}%` }}></div>
                </div>
             </div>
          </div>
        </div>
        {/* Badges Section */}
        <div className="profile-section-card">
          <h3>🏅 Badges</h3>
          <p>Complete quizzes to earn badges!</p>
        </div>
      </div>
    </div>
  );
}
